# emlog.map — the functions libemlog.so exports, under the version node EMLOG_<major> (the soname major): exactly the
# functions app/emlog.h declares (the `function` lines of abi/layout.txt; utils/check_abi.sh --exports refuses any difference).
# Everything else stays local. The .a archive is unaffected.
EMLOG_1 {
  global:
    emlog_dropped_lines;
    emlog_enable_timestamps;
    emlog_init;
    emlog_log;
    emlog_log_errno;
    emlog_set_journal_mode;
    emlog_set_level;
    emlog_set_writer;
    emlog_set_writev_flush;
  local:
    *;
};
